// LTC tables for isotropic GGX (height-correlated Smith G2), 64 x 64.
// Fitted offline for this engine with the method of Heitz, Dupuy, Hill & Neubelt 2016
// ("Real-Time Polygonal-Light Shading with Linearly Transformed Cosines"):
// Nelder-Mead minimisation of the MIS-weighted L3 error between the LTC and the BRDF.
//   index  = roughnessIndex * 64 + thetaIndex
//   roughness = roughnessIndex / 63 (perceptual, alpha = roughness^2)
//   theta     : sqrt(1 - NdotV) = thetaIndex / 63
//   g_kLtcMatrix : inverse LTC matrix normalised by m11: (m00, m02, m20, m22),
//                  M^-1 = [[m00, 0, m02], [0, 1, 0], [m20, 0, m22]] in the frame (T1, T2, N)
//                  with V = (sin, 0, cos).
//   g_kLtcAmplitude : (integral of BRDF*cos, integral of BRDF*cos*(1 - V.H)^5)
//                     = split-sum DFG: Fss*Ess = F0 * (x - y) + y.
// =============================================================================================
